DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.submit_delivery(uuid,uuid[],timestamptz,text,boolean)'::regprocedure) INTO d; d:=replace(d,'intended:=CASE WHEN _when IS NULL THEN ''immediate'' ELSE ''scheduled'' END;','intended:=''delivery'';'); EXECUTE d;
SELECT pg_get_functiondef('public.reconcile_delivery(uuid,text,text,text)'::regprocedure) INTO d; d:=replace(d,'IF o.id IS NULL OR o.status=''platform_confirmed'' THEN RETURN; END IF;','IF o.id IS NULL THEN RAISE EXCEPTION ''Unknown delivery operation''; END IF;
IF o.status=''platform_confirmed'' OR (o.status=_outcome AND o.platform_post_id IS NOT DISTINCT FROM _platform_post_id) THEN RETURN; END IF;
IF o.status NOT IN (''sending'',''awaiting_confirmation'') THEN RAISE EXCEPTION ''Only an in-flight delivery can receive a provider result''; END IF;
IF _outcome=''sending'' AND o.status<>''sending'' THEN RAISE EXCEPTION ''Unknown outcomes must be reconciled before a new attempt''; END IF;'); EXECUTE d;
SELECT pg_get_functiondef('public.cancel_delivery_schedule(uuid)'::regprocedure) INTO d; d:=replace(d,'UPDATE public.delivery_operations SET status=''skipped''','IF NOT EXISTS(SELECT 1 FROM public.delivery_operations WHERE post_card_id=p.id AND status=''scheduled'') OR EXISTS(SELECT 1 FROM public.delivery_operations WHERE post_card_id=p.id AND status IN (''sending'',''awaiting_confirmation'',''platform_confirmed'')) THEN RAISE EXCEPTION ''Only pending operations may be canceled''; END IF; UPDATE public.delivery_operations SET status=''skipped'''); EXECUTE d;
SELECT pg_get_functiondef('public.acknowledge_preflight(uuid,text)'::regprocedure) INTO d; d:=replace(d,'''Preflight advisory findings acknowledged for revision ''||p.readiness_revision','''Preflight advisory findings acknowledged for revision ''||p.readiness_revision||CASE WHEN nullif(trim(_reason),'''') IS NOT NULL THEN '' · Reason: ''||left(_reason,1000) ELSE '''' END'); EXECUTE d;
END $$;
COMMENT ON COLUMN public.delivery_operations.intent IS 'Stable logical delivery slot (delivery), independent of retries and mutable intended_at. One slot per workspace/post revision/account; rescheduling updates the slot.';